<script lang="ts">
import {can} from '$lib/auth/policy';
import {page} from '$app/state';
const canManageDependencies=$derived(can(page.data.context??null,'task.manage.dependencies'));
const canEditProject=$derived(can(page.data.context??null,'project.edit'));
const canArchiveProject=$derived(can(page.data.context??null,'project.archive'));
let successorTaskId=$state(''),projectStatus=$state('planning');
const projectStatuses=['planning','active','on_hold','completed','cancelled','archived'];
type FormEvent<T=HTMLFormElement>=SubmitEvent&{currentTarget:T};
import SvgIcon from "$lib/components/ui/Icon.svelte";
import Button from "$lib/components/ui/Button.svelte";
import Card from "$lib/components/ui/Card.svelte";
import CardContent from "$lib/components/ui/CardContent.svelte";
import CardHeader from "$lib/components/ui/CardHeader.svelte";
import CardTitle from "$lib/components/ui/CardTitle.svelte";
import Input from "$lib/components/ui/Input.svelte";
import Badge from "$lib/components/ui/Badge.svelte";

import {untrack} from "svelte";
import {page as routePage,navigating} from "$app/state";
import {goto,invalidateAll} from "$app/navigation";
import {notify} from "$lib/client/toast";
type Project = { id: string; projectNumber: string; name: string; description?: string | null; status: string; priority: string; startDate?: string | null; targetEndDate?: string | null };
type Task = { id: string; taskNumber: string; title: string; description?: string | null; status: string; priority: string; dueDate?: string | null; projectId?: string | null; assigneeEmployeeId?: string | null };
type Employee = { id: string; displayName: string; employeeId: string; status: string };
type ConversationRow = { conversation: { id: string; type: string; name?: string | null; updatedAt: string }; employee: Employee };
type Message = { id: string; content?: string | null; senderEmployeeId: string; createdAt: string; type: string };
type ProjectDetail = { project: Project; members: Array<{ membership: { employeeId: string; role: string }; employee: Employee }>; tasks: Task[]; activity: Array<{ id: string; activityType: string; createdAt: string }> };
type TaskDetail = { task: Task; comments: Array<{ comment: { id: string; content: string; createdAt: string }; employee: Employee }>; activity: Array<{ id: string; activityType: string; createdAt: string }> };
const statuses = ["todo", "in_progress", "blocked", "in_review", "completed", "cancelled"];
const priorities = ["low", "medium", "high", "urgent"];
async function requestJson<T>(url: string, options?: RequestInit): Promise<T> { const response = await fetch(url, { ...options, cache:"no-store", headers: { "content-type": "application/json", ...(options?.headers ?? {}) } }); const body = await response.json().catch(() => ({})); if (!response.ok || body.success !== true) throw new Error(body?.error?.message ?? "The request could not be completed."); return body as T; }
function formatDate(value?: string | null) { return value ? new Intl.DateTimeFormat(undefined, { dateStyle: "medium" }).format(new Date(value)) : "No date"; }
function label(value: string) { return value.replaceAll("_", " ").replace(/\b\w/g, (character) => character.toUpperCase()); }
let { initialView = "work" }:{ initialView?: "work" | "chat" }=$props();
let view=$state(untrack(()=>(initialView)));
const setView=(next:typeof view|((previous:typeof view)=>typeof view))=>{view=typeof next==="function"?(next as (previous:typeof view)=>typeof view)(view):next;};
let projects=$state<Project[]>(untrack(()=>([])));
const setProjects=(next:typeof projects|((previous:typeof projects)=>typeof projects))=>{projects=typeof next==="function"?(next as (previous:typeof projects)=>typeof projects)(projects):next;};
let tasks=$state<Task[]>(untrack(()=>([])));
const setTasks=(next:typeof tasks|((previous:typeof tasks)=>typeof tasks))=>{tasks=typeof next==="function"?(next as (previous:typeof tasks)=>typeof tasks)(tasks):next;};
let employees=$state<Employee[]>(untrack(()=>([])));
const setEmployees=(next:typeof employees|((previous:typeof employees)=>typeof employees))=>{employees=typeof next==="function"?(next as (previous:typeof employees)=>typeof employees)(employees):next;};
let conversations=$state<ConversationRow[]>(untrack(()=>([])));
const setConversations=(next:typeof conversations|((previous:typeof conversations)=>typeof conversations))=>{conversations=typeof next==="function"?(next as (previous:typeof conversations)=>typeof conversations)(conversations):next;};
let projectDetail=$state<ProjectDetail | null>(untrack(()=>(null)));
const setProjectDetail=(next:typeof projectDetail|((previous:typeof projectDetail)=>typeof projectDetail))=>{projectDetail=typeof next==="function"?(next as (previous:typeof projectDetail)=>typeof projectDetail)(projectDetail):next;};
let taskDetail=$state<TaskDetail | null>(untrack(()=>(null)));
const setTaskDetail=(next:typeof taskDetail|((previous:typeof taskDetail)=>typeof taskDetail))=>{taskDetail=typeof next==="function"?(next as (previous:typeof taskDetail)=>typeof taskDetail)(taskDetail):next;};
let messages=$state<Message[]>(untrack(()=>([])));
const setMessages=(next:typeof messages|((previous:typeof messages)=>typeof messages))=>{messages=typeof next==="function"?(next as (previous:typeof messages)=>typeof messages)(messages):next;};
let conversationId=$state(untrack(()=>("")));
const setConversationId=(next:typeof conversationId|((previous:typeof conversationId)=>typeof conversationId))=>{conversationId=typeof next==="function"?(next as (previous:typeof conversationId)=>typeof conversationId)(conversationId):next;};
let busy=$state(untrack(()=>(false)));
const setBusy=(next:typeof busy|((previous:typeof busy)=>typeof busy))=>{busy=typeof next==="function"?(next as (previous:typeof busy)=>typeof busy)(busy):next;};
let loading=$state(untrack(()=>(true)));
const setLoading=(next:typeof loading|((previous:typeof loading)=>typeof loading))=>{loading=typeof next==="function"?(next as (previous:typeof loading)=>typeof loading)(loading):next;};
let error=$state(untrack(()=>("")));
const setError=(next:typeof error|((previous:typeof error)=>typeof error))=>{error=typeof next==="function"?(next as (previous:typeof error)=>typeof error)(error):next;};
let notice=$state(untrack(()=>("")));
const setNotice=(next:typeof notice|((previous:typeof notice)=>typeof notice))=>{notice=typeof next==="function"?(next as (previous:typeof notice)=>typeof notice)(notice):next;};
let projectForm=$state(untrack(()=>({ name: "", description: "", priority: "medium", startDate: "", targetEndDate: "" })));
const setProjectForm=(next:typeof projectForm|((previous:typeof projectForm)=>typeof projectForm))=>{projectForm=typeof next==="function"?(next as (previous:typeof projectForm)=>typeof projectForm)(projectForm):next;};
let taskForm=$state(untrack(()=>({ title: "", description: "", projectId: "", assigneeEmployeeId: "", priority: "medium", dueDate: "" })));
const setTaskForm=(next:typeof taskForm|((previous:typeof taskForm)=>typeof taskForm))=>{taskForm=typeof next==="function"?(next as (previous:typeof taskForm)=>typeof taskForm)(taskForm):next;};
let chatForm=$state(untrack(()=>({ employeeId: "", content: "" })));
const setChatForm=(next:typeof chatForm|((previous:typeof chatForm)=>typeof chatForm))=>{chatForm=typeof next==="function"?(next as (previous:typeof chatForm)=>typeof chatForm)(chatForm):next;};
let memberEmployeeId=$state(untrack(()=>("")));
const setMemberEmployeeId=(next:typeof memberEmployeeId|((previous:typeof memberEmployeeId)=>typeof memberEmployeeId))=>{memberEmployeeId=typeof next==="function"?(next as (previous:typeof memberEmployeeId)=>typeof memberEmployeeId)(memberEmployeeId):next;};
let convertMessage=$state<Message | null>(untrack(()=>(null)));
const setConvertMessage=(next:typeof convertMessage|((previous:typeof convertMessage)=>typeof convertMessage))=>{convertMessage=typeof next==="function"?(next as (previous:typeof convertMessage)=>typeof convertMessage)(convertMessage):next;};
const loadWork=$derived.by(()=>{return async () => { setLoading(true); setError(""); try { const [projectBody, taskBody, employeeBody] = await Promise.all([requestJson<{ projects: Project[] }>("/api/app/projects"), requestJson<{ tasks: Task[] }>("/api/app/tasks"), requestJson<{ rows: Employee[] }>("/api/app/employees?pageSize=100")]); setProjects(projectBody.projects ?? []); setTasks(taskBody.tasks ?? []); setEmployees(employeeBody.rows ?? []); } catch (cause) { setError(cause instanceof Error ? cause.message : "Work data could not be loaded."); } finally { setLoading(false); } };});
const loadChat=$derived.by(()=>{return async () => { setLoading(true); setError(""); try { const [conversationBody, employeeBody] = await Promise.all([requestJson<{ conversations: ConversationRow[] }>("/api/app/chat/conversations"), requestJson<{ rows: Employee[] }>("/api/app/employees?pageSize=100")]); setConversations(conversationBody.conversations ?? []); setEmployees(employeeBody.rows ?? []); } catch (cause) { setError(cause instanceof Error ? cause.message : "Chat data could not be loaded."); } finally { setLoading(false); } };});
$effect(()=>{loadChat;loadWork;view;return untrack(() => { void (view === "chat" ? loadChat() : loadWork()); });});
async function createProject(event: FormEvent) { event.preventDefault(); if(busy)return; setBusy(true); setError(""); setNotice(""); try { await requestJson("/api/app/projects", { method: "POST", body: JSON.stringify(projectForm) }); setProjectForm({ name: "", description: "", priority: "medium", startDate: "", targetEndDate: "" }); setNotice("Project created."); await loadWork(); } catch (cause) { setError(cause instanceof Error ? cause.message : "Project could not be created."); } finally { setBusy(false); } }
async function createTask(event: FormEvent) { event.preventDefault(); if(busy)return; setBusy(true); setError(""); setNotice(""); try { await requestJson("/api/app/tasks", { method: "POST", body: JSON.stringify({ ...taskForm, projectId: taskForm.projectId || undefined, assigneeEmployeeId: taskForm.assigneeEmployeeId || undefined, dueDate: taskForm.dueDate || undefined }) }); setTaskForm({ title: "", description: "", projectId: "", assigneeEmployeeId: "", priority: "medium", dueDate: "" }); setNotice("Task created."); await loadWork(); } catch (cause) { setError(cause instanceof Error ? cause.message : "Task could not be created."); } finally { setBusy(false); } }
let detailRequest=0;
async function openProject(id:string){const request=++detailRequest;setError('');setProjectDetail(null);setTaskDetail(null);try{const detail=await requestJson<ProjectDetail>(`/api/app/projects/${encodeURIComponent(id)}`);if(request===detailRequest){setProjectDetail(detail);projectStatus=detail.project.status;}}catch(cause){if(request===detailRequest)setError(cause instanceof Error?cause.message:'Project could not be loaded.');}}
async function openTask(id:string){const request=++detailRequest;setError('');setProjectDetail(null);setTaskDetail(null);try{const detail=await requestJson<TaskDetail>(`/api/app/tasks/${encodeURIComponent(id)}`);if(request===detailRequest){setTaskDetail(detail);successorTaskId="";}}catch(cause){if(request===detailRequest)setError(cause instanceof Error?cause.message:'Task could not be loaded.');}}
async function saveProjectStatus(event:SubmitEvent){
 event.preventDefault();if(busy||!projectDetail||!projectStatuses.includes(projectStatus)||!(projectStatus==='archived'?canArchiveProject:canEditProject))return;
 const id=projectDetail.project.id;setBusy(true);setError('');setNotice('');
 try{await requestJson(`/api/app/projects/${encodeURIComponent(id)}`,{method:'PATCH',body:JSON.stringify({status:projectStatus})});setNotice('Project status updated.');await openProject(id);await loadWork();}
 catch(cause){setError(cause instanceof Error?cause.message:'Project status could not be updated.');}finally{setBusy(false);}
}
async function addDependency(event:SubmitEvent){
 event.preventDefault();if(busy||!taskDetail||!canManageDependencies||!successorTaskId||successorTaskId===taskDetail.task.id)return;
 const id=taskDetail.task.id;setBusy(true);setError('');setNotice('');
 try{await requestJson(`/api/app/tasks/${encodeURIComponent(id)}`,{method:'POST',body:JSON.stringify({action:'dependency',successorTaskId})});successorTaskId='';setNotice('Dependency added.');}
 catch(cause){setError(cause instanceof Error?cause.message:'Dependency could not be added.');}finally{setBusy(false);}
}
async function updateTask(data: Record<string, unknown>) { if (!taskDetail || busy) return; if(busy)return; setBusy(true); setError(""); try { await requestJson(`/api/app/tasks/${taskDetail.task.id}`, { method: "PATCH", body: JSON.stringify(data) }); setNotice("Task updated."); await openTask(taskDetail!.task.id); await loadWork(); } catch (cause) { setError(cause instanceof Error ? cause.message : "Task could not be updated."); } finally { setBusy(false); } }
async function addComment(event: FormEvent<HTMLFormElement>) { event.preventDefault(); if (!taskDetail || busy) return; const formElement=event.currentTarget;const form = new FormData(formElement); const content = String(form.get("content") ?? "").trim(); if (!content) return; setBusy(true); setError(""); setNotice(""); try { await requestJson(`/api/app/tasks/${taskDetail.task.id}`, { method: "POST", body: JSON.stringify({ content }) }); formElement.reset(); setNotice("Comment added."); await openTask(taskDetail!.task.id); } catch (cause) { setError(cause instanceof Error ? cause.message : "Comment could not be added."); } finally { setBusy(false); } }
async function manageMember(action: "add_member" | "remove_member", employeeId: string) { if (!projectDetail || busy) return; setBusy(true); setError(""); setNotice(""); try { await requestJson(`/api/app/projects/${projectDetail.project.id}`, { method: "POST", body: JSON.stringify({ action, employeeId }) }); setNotice(action === "add_member" ? "Member added." : "Member removed."); setMemberEmployeeId(""); await openProject(projectDetail!.project.id); } catch (cause) { setError(cause instanceof Error ? cause.message : "Project membership could not be changed."); } finally { setBusy(false); } }
async function openConversation(id: string) { setConversationId(id); setError(""); try { const body = await requestJson<{ messages: Message[] }>(`/api/app/chat/conversations/${id}/messages`); setMessages(body.messages ?? []); } catch (cause) { setError(cause instanceof Error ? cause.message : "Messages could not be loaded."); } }
async function createConversation(event: FormEvent) { event.preventDefault(); if (busy || !chatForm.employeeId) return; setBusy(true); setError(""); setNotice(""); try { const body = await requestJson<{ conversation: { id: string } }>("/api/app/chat/conversations", { method: "POST", body: JSON.stringify({ type: "direct", employeeIds: [chatForm.employeeId] }) }); setNotice("Conversation created."); await loadChat(); await openConversation(body.conversation.id); } catch (cause) { setError(cause instanceof Error ? cause.message : "Conversation could not be created."); } finally { setBusy(false); } }
async function sendMessage(event: FormEvent) { event.preventDefault(); if (busy || !conversationId || !chatForm.content.trim()) return; setBusy(true); setError(""); setNotice(""); try { await requestJson(`/api/app/chat/conversations/${conversationId}/messages`, { method: "POST", body: JSON.stringify({ content: chatForm.content.trim(), clientIdempotencyKey: crypto.randomUUID() }) }); setChatForm({ ...chatForm, content: "" }); await openConversation(conversationId); } catch (cause) { setError(cause instanceof Error ? cause.message : "Message could not be sent."); } finally { setBusy(false); } }
async function convertToTask(event: FormEvent<HTMLFormElement>) { event.preventDefault(); if (busy || !convertMessage) return; const formElement=event.currentTarget;const form = new FormData(formElement); setBusy(true); setError(""); setNotice(""); try { await requestJson(`/api/app/chat/messages/${convertMessage.id}/task`, { method: "POST", body: JSON.stringify({ title: String(form.get("title") ?? ""), description: convertMessage.content ?? undefined, projectId: String(form.get("projectId") ?? "") || undefined, assigneeEmployeeId: String(form.get("assigneeEmployeeId") ?? "") || undefined, dueDate: String(form.get("dueDate") ?? "") || undefined, priority: String(form.get("priority") ?? "medium") }) }); setConvertMessage(null); setNotice("Task created from the message."); } catch (cause) { setError(cause instanceof Error ? cause.message : "The message could not be converted."); } finally { setBusy(false); } }
const conversationNames=$derived.by(() => conversations.map((row) => ({ ...row, title: row.conversation.name || row.employee.displayName })));
</script>
<div class="space-y-5">
    <div class="flex flex-wrap gap-2" role="tablist" aria-label="Work areas"><Button variant={view === "work" ? "primary" : "secondary"} onclick={() => { setView("work"); setProjectDetail(null); setTaskDetail(null); }}>Projects & tasks</Button><Button variant={view === "chat" ? "primary" : "secondary"} onclick={() => { setView("chat"); setProjectDetail(null); setTaskDetail(null); }}>Internal chat</Button></div>
    {#if error}<p role="alert" class="rounded-lg border border-danger/30 bg-danger/5 p-3 text-sm text-danger">{error}</p>{/if}{#if notice}<p role="status" class="rounded-lg border border-success/30 bg-success/5 p-3 text-sm text-success">{notice}</p>{/if}
    {#if loading}<Card><CardContent class="p-6 text-sm text-muted">Loading workspace…</CardContent></Card>{:else}{#if view === "chat"}<div class="grid gap-5 lg:grid-cols-[minmax(230px,0.35fr)_1fr]"><Card><CardHeader><CardTitle>Conversations</CardTitle></CardHeader><CardContent class="space-y-2">{#if conversationNames.length}{#each conversationNames as row}<button type="button" onclick={() => void openConversation(row.conversation.id)} class="w-full rounded-lg border p-3 text-left hover:bg-surface"><p class="font-medium">{row.title}</p><p class="text-xs text-muted">{label(row.conversation.type)} · {formatDate(row.conversation.updatedAt)}</p></button>{/each}{:else}<p class="text-sm text-muted">No conversations yet.</p>{/if}<form onsubmit={createConversation} class="space-y-2 border-t pt-4"><label class="text-sm font-medium" for="chat-employee">Start a conversation</label><select id="chat-employee" value={chatForm.employeeId} onchange={(event) => setChatForm({ ...chatForm, employeeId: event.currentTarget.value })} class="h-10 w-full rounded-lg border bg-background px-3 text-sm"><option value="">Choose an organization member</option>{#each employees as employee}<option value={employee.id}>{employee.displayName}</option>{/each}</select><Button type="submit" disabled={busy || !chatForm.employeeId} class="w-full">New direct chat</Button></form></CardContent></Card><Card><CardHeader><CardTitle>{#if conversationId}{"Messages"}{:else}{"Select a conversation"}{/if}</CardTitle></CardHeader><CardContent class="space-y-4">{#if conversationId}<div class="max-h-[480px] space-y-3 overflow-y-auto" aria-live="polite">{#if messages.length}{#each messages as message}<div class="rounded-lg border p-3"><p class="whitespace-pre-wrap text-sm">{message.content || "Attachment message"}</p><div class="mt-2 flex items-center justify-between text-xs text-muted"><span>{formatDate(message.createdAt)}</span><Button variant="ghost" size="sm" onclick={() => setConvertMessage(message)}>Create task</Button></div></div>{/each}{:else}<p class="text-sm text-muted">No messages yet.</p>{/if}</div><form onsubmit={sendMessage} class="flex gap-2"><Input aria-label="Message" placeholder="Write a message…" value={chatForm.content} oninput={(event) => setChatForm({ ...chatForm, content: event.currentTarget.value })} /><Button type="submit" disabled={busy || !chatForm.content.trim()}>Send</Button></form>{:else}<p class="text-sm text-muted">Choose a conversation to read its organization-scoped message history.</p>{/if}</CardContent></Card></div>{:else}
      {#if !projectDetail && !taskDetail}<div class="grid gap-5 lg:grid-cols-2"><Card><CardHeader><CardTitle>Create project</CardTitle></CardHeader><CardContent><form onsubmit={createProject} class="grid gap-3"><Input required aria-label="Project name" placeholder="Project name" value={projectForm.name} oninput={(event) => setProjectForm({ ...projectForm, name: event.currentTarget.value })} /><textarea aria-label="Project description" placeholder="Description (optional)" value={projectForm.description} oninput={(event) => setProjectForm({ ...projectForm, description: event.currentTarget.value })} class="min-h-20 rounded-lg border bg-background p-3 text-sm"></textarea><div class="grid gap-3 sm:grid-cols-3"><select aria-label="Project priority" value={projectForm.priority} onchange={(event) => setProjectForm({ ...projectForm, priority: event.currentTarget.value })} class="h-10 rounded-lg border bg-background px-3 text-sm">{#each priorities as value}<option>{value}</option>{/each}</select><Input aria-label="Project start date" type="date" value={projectForm.startDate} oninput={(event) => setProjectForm({ ...projectForm, startDate: event.currentTarget.value })} /><Input aria-label="Project target end date" type="date" value={projectForm.targetEndDate} oninput={(event) => setProjectForm({ ...projectForm, targetEndDate: event.currentTarget.value })} /></div><Button type="submit" disabled={busy}>Create project</Button></form></CardContent></Card><Card><CardHeader><CardTitle>Create task</CardTitle></CardHeader><CardContent><form onsubmit={createTask} class="grid gap-3"><Input required aria-label="Task title" placeholder="Task title" value={taskForm.title} oninput={(event) => setTaskForm({ ...taskForm, title: event.currentTarget.value })} /><textarea aria-label="Task description" placeholder="Description (optional)" value={taskForm.description} oninput={(event) => setTaskForm({ ...taskForm, description: event.currentTarget.value })} class="min-h-20 rounded-lg border bg-background p-3 text-sm"></textarea><div class="grid gap-3 sm:grid-cols-2"><select aria-label="Task project" value={taskForm.projectId} onchange={(event) => setTaskForm({ ...taskForm, projectId: event.currentTarget.value })} class="h-10 rounded-lg border bg-background px-3 text-sm"><option value="">No project</option>{#each projects as project}<option value={project.id}>{project.name}</option>{/each}</select><select aria-label="Task assignee" value={taskForm.assigneeEmployeeId} onchange={(event) => setTaskForm({ ...taskForm, assigneeEmployeeId: event.currentTarget.value })} class="h-10 rounded-lg border bg-background px-3 text-sm"><option value="">Unassigned</option>{#each employees as employee}<option value={employee.id}>{employee.displayName}</option>{/each}</select><select aria-label="Task priority" value={taskForm.priority} onchange={(event) => setTaskForm({ ...taskForm, priority: event.currentTarget.value })} class="h-10 rounded-lg border bg-background px-3 text-sm">{#each priorities as value}<option>{value}</option>{/each}</select><Input aria-label="Task due date" type="date" value={taskForm.dueDate} oninput={(event) => setTaskForm({ ...taskForm, dueDate: event.currentTarget.value })} /></div><Button type="submit" disabled={busy}>Create task</Button></form></CardContent></Card></div>{/if}
      {#if !projectDetail && !taskDetail}<div class="grid gap-5 lg:grid-cols-2"><Card><CardHeader><CardTitle>Projects</CardTitle></CardHeader><CardContent class="space-y-2">{#if projects.length}{#each projects as project}<button type="button" onclick={() => void openProject(project.id)} class="w-full rounded-lg border p-3 text-left hover:bg-surface"><div class="flex items-center justify-between gap-3"><span class="font-medium">{project.name}</span><Badge>{label(project.status)}</Badge></div><p class="mt-1 text-xs text-muted">{project.projectNumber} · {label(project.priority)} · {formatDate(project.targetEndDate)}</p></button>{/each}{:else}<p class="text-sm text-muted">No projects are visible yet.</p>{/if}</CardContent></Card><Card><CardHeader><CardTitle>Tasks</CardTitle></CardHeader><CardContent class="space-y-2">{#if tasks.length}{#each tasks as task}<button type="button" onclick={() => void openTask(task.id)} class="w-full rounded-lg border p-3 text-left hover:bg-surface"><div class="flex items-center justify-between gap-3"><span class="font-medium">{task.title}</span><Badge>{label(task.status)}</Badge></div><p class="mt-1 text-xs text-muted">{task.taskNumber} · {label(task.priority)} · due {formatDate(task.dueDate)}</p></button>{/each}{:else}<p class="text-sm text-muted">No tasks are visible yet.</p>{/if}</CardContent></Card></div>{/if}
      {#if projectDetail}{#if canEditProject || canArchiveProject}<form onsubmit={saveProjectStatus} class="flex flex-wrap items-end gap-3 rounded-xl border p-4"><label class="grid gap-1 text-sm">Project status<select aria-label="Project status" class="h-10 rounded-lg border bg-surface px-3" bind:value={projectStatus} disabled={busy}>{#each projectStatuses as value}<option value={value} disabled={value==='archived'?!canArchiveProject:!canEditProject}>{label(value)}</option>{/each}</select></label><Button type="submit" disabled={busy}>Save project status</Button></form>{/if}<Card><CardHeader><Button variant="ghost" size="sm" onclick={() => setProjectDetail(null)}>← Back</Button><div class="mt-2 flex items-center justify-between gap-3"><div><CardTitle>{projectDetail.project.name}</CardTitle><p class="mt-1 text-sm text-muted">{projectDetail.project.description || "No description"}</p></div><Badge>{label(projectDetail.project.status)}</Badge></div></CardHeader><CardContent class="grid gap-5 lg:grid-cols-2"><section><h3 class="font-semibold">Members</h3><div class="mt-3 space-y-2">{#each projectDetail.members as { membership, employee }}<div class="flex items-center justify-between rounded-lg border p-3"><span>{employee.displayName}<span class="ml-2 text-xs text-muted">{label(membership.role)}</span></span>{#if membership.role === "member"}<Button variant="ghost" size="sm" onclick={() => void manageMember("remove_member", employee.id)}>Remove</Button>{/if}</div>{/each}</div><div class="mt-3 flex gap-2"><select aria-label="Add project member" value={memberEmployeeId} onchange={(event) => setMemberEmployeeId(event.currentTarget.value)} class="h-10 min-w-0 flex-1 rounded-lg border bg-background px-3 text-sm"><option value="">Add a member</option>{#each employees.filter((employee) => !projectDetail?.members.some((member) => member.employee.id === employee.id)) as employee}<option value={employee.id}>{employee.displayName}</option>{/each}</select><Button disabled={busy || !memberEmployeeId} onclick={() => void manageMember("add_member", memberEmployeeId)}>Add</Button></div></section><section><h3 class="font-semibold">Project tasks</h3><div class="mt-3 space-y-2">{#if projectDetail.tasks.length}{#each projectDetail.tasks as task}<button type="button" onclick={() => void openTask(task.id)} class="w-full rounded-lg border p-3 text-left hover:bg-surface"><div class="flex justify-between"><span>{task.title}</span><Badge>{label(task.status)}</Badge></div><p class="text-xs text-muted">{task.taskNumber} · {formatDate(task.dueDate)}</p></button>{/each}{:else}<p class="text-sm text-muted">No tasks in this project.</p>{/if}</div></section><section class="lg:col-span-2"><h3 class="font-semibold">Activity</h3><div class="mt-3 space-y-2">{#if projectDetail.activity.length}{#each projectDetail.activity as item}<p class="rounded-lg border p-3 text-sm">{label(item.activityType)} <span class="text-xs text-muted">· {formatDate(item.createdAt)}</span></p>{/each}{:else}<p class="text-sm text-muted">No activity recorded yet.</p>{/if}</div></section></CardContent></Card>{/if}
      {#if taskDetail}{#if canManageDependencies}<form onsubmit={addDependency} class="grid gap-3 rounded-xl border p-4"><p class="text-sm text-muted">Link this task as a prerequisite for another task.</p><label class="grid gap-1 text-sm">Successor task<select required class="h-10 rounded-lg border bg-surface px-3" bind:value={successorTaskId} disabled={busy}><option value="">Select a task</option>{#each tasks.filter(task=>task.id!==taskDetail!.task.id) as task}<option value={task.id}>{task.title}</option>{/each}</select></label><Button type="submit" disabled={busy||!successorTaskId}>Add dependency</Button></form>{/if}<Card><CardHeader><Button variant="ghost" size="sm" onclick={() => setTaskDetail(null)}>← Back</Button><div class="mt-2 flex items-center justify-between gap-3"><div><CardTitle>{taskDetail.task.title}</CardTitle><p class="mt-1 text-sm text-muted">{taskDetail.task.description || "No description"}</p></div><Badge>{label(taskDetail.task.status)}</Badge></div></CardHeader><CardContent class="space-y-5"><div class="flex flex-wrap gap-2"><select aria-label="Task status" value={taskDetail.task.status} onchange={(event) => void updateTask({ status: event.currentTarget.value })} class="h-10 rounded-lg border bg-background px-3 text-sm">{#each statuses as value}<option>{value}</option>{/each}</select><select aria-label="Task priority" value={taskDetail.task.priority} onchange={(event) => void updateTask({ priority: event.currentTarget.value })} class="h-10 rounded-lg border bg-background px-3 text-sm">{#each priorities as value}<option>{value}</option>{/each}</select><select aria-label="Task assignee" value={taskDetail.task.assigneeEmployeeId ?? ""} onchange={(event) => void updateTask({ assigneeEmployeeId: event.currentTarget.value || null })} class="h-10 rounded-lg border bg-background px-3 text-sm"><option value="">Unassigned</option>{#each employees as employee}<option value={employee.id}>{employee.displayName}</option>{/each}</select><Input aria-label="Task due date" type="date" value={taskDetail.task.dueDate ?? ""} oninput={(event) => void updateTask({ dueDate: event.currentTarget.value || null })} class="w-44" /></div><section><h3 class="font-semibold">Comments</h3><div class="mt-3 space-y-2">{#if taskDetail.comments.length}{#each taskDetail.comments as { comment, employee }}<div class="rounded-lg border p-3"><p class="text-sm">{comment.content}</p><p class="mt-1 text-xs text-muted">{employee.displayName} · {formatDate(comment.createdAt)}</p></div>{/each}{:else}<p class="text-sm text-muted">No comments yet.</p>{/if}</div><form onsubmit={addComment} class="mt-3 flex gap-2"><Input name="content" aria-label="Task comment" placeholder="Add a comment…" /><Button type="submit" disabled={busy}>Comment</Button></form></section><section><h3 class="font-semibold">Activity</h3><div class="mt-3 space-y-2">{#if taskDetail.activity.length}{#each taskDetail.activity as item}<p class="rounded-lg border p-3 text-sm">{label(item.activityType)} <span class="text-xs text-muted">· {formatDate(item.createdAt)}</span></p>{/each}{:else}<p class="text-sm text-muted">No activity recorded yet.</p>{/if}</div></section></CardContent></Card>{/if}
    {/if}{/if}
    {#if convertMessage}<div class="fixed inset-0 z-30 grid place-items-center bg-black/40 p-4"><Card class="w-full max-w-lg"><CardHeader><CardTitle>Create task from message</CardTitle></CardHeader><CardContent><form onsubmit={convertToTask} class="grid gap-3"><Input required name="title" aria-label="Task title from message" value={convertMessage.content ?? ""} /><select name="projectId" aria-label="Task project" class="h-10 rounded-lg border bg-background px-3 text-sm"><option value="">No project</option>{#each projects as project}<option value={project.id}>{project.name}</option>{/each}</select><select name="assigneeEmployeeId" aria-label="Task assignee" class="h-10 rounded-lg border bg-background px-3 text-sm"><option value="">Unassigned</option>{#each employees as employee}<option value={employee.id}>{employee.displayName}</option>{/each}</select><div class="grid gap-3 sm:grid-cols-2"><select name="priority" aria-label="Task priority" class="h-10 rounded-lg border bg-background px-3 text-sm">{#each priorities as value}<option>{value}</option>{/each}</select><Input name="dueDate" aria-label="Task due date" type="date" /></div><div class="flex justify-end gap-2"><Button type="button" variant="secondary" onclick={() => setConvertMessage(null)}>Cancel</Button><Button type="submit" disabled={busy}>Create task</Button></div></form></CardContent></Card></div>{/if}
  </div>
